import{_ as l,C as c,o,c as u,a2 as t,b as r,w as a,a as n,E as s,a3 as d}from"./chunks/framework.CgxQ0r6v.js";const v=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 2","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-IV/Lectura_Catedra_Evaluacion_2.md","filePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-IV/Lectura_Catedra_Evaluacion_2.md"}'),m={name:"materias/Proyecto_Sociotecnologico_II/documentacion/II-IV/Lectura_Catedra_Evaluacion_2.md"};function f(p,e,b,g,h,q){const i=c("Mermaid");return o(),u("div",null,[e[2]||(e[2]=t('<h1 id="manual-de-estudio-profundo-evaluacion-2" tabindex="-1">Manual de Estudio Profundo: Evaluación 2 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-2" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 2&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-iv" tabindex="-1">Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre IV) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-iv" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre IV)&quot;">​</a></h2><h3 id="eje-tematico-ingenieria-de-requerimientos-y-levantamiento-de-informacion" tabindex="-1">Eje Temático: Ingeniería de Requerimientos y Levantamiento de Información <a class="header-anchor" href="#eje-tematico-ingenieria-de-requerimientos-y-levantamiento-de-informacion" aria-label="Permalink to &quot;Eje Temático: Ingeniería de Requerimientos y Levantamiento de Información&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-base-de-todo-sistema-de-informacion" tabindex="-1">🧭 Introducción: La Base de Todo Sistema de Información <a class="header-anchor" href="#🧭-introduccion-la-base-de-todo-sistema-de-informacion" aria-label="Permalink to &quot;🧭 Introducción: La Base de Todo Sistema de Información&quot;">​</a></h2><p>El 60% de los proyectos informáticos que fracasan o son abandonados no fallan por problemas de código o de hardware, sino porque <strong>los desarrolladores construyeron exactamente lo que no se necesitaba</strong>, producto de un levantamiento de requerimientos deficiente o ambiguo.</p><p>En el Proyecto Sociotecnológico II (PST II), la <strong>Ingeniería de Requerimientos</strong> es la disciplina que permite traducir las necesidades orales, los dolores cotidianos y las rutinas manuales de la comunidad a un conjunto formal, verificable y estructurado de especificaciones de software.</p><hr><h2 id="🏛️-capitulo-i-tecnicas-e-instrumentos-de-recoleccion-de-datos" tabindex="-1">🏛️ CAPÍTULO I: Técnicas e Instrumentos de Recolección de Datos <a class="header-anchor" href="#🏛️-capitulo-i-tecnicas-e-instrumentos-de-recoleccion-de-datos" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Técnicas e Instrumentos de Recolección de Datos&quot;">​</a></h2><p>Para descubrir qué debe hacer el sistema, el equipo de desarrollo debe emplear técnicas científicas de recolección de información cualitativa y cuantitativa.</p>',10)),(o(),r(d,null,{default:a(()=>[s(i,{id:"mermaid-26",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20T%5B%22%F0%9F%9B%A0%EF%B8%8F%20T%C3%A9cnicas%20de%20Levantamiento%22%5D%0A%20%20%20%20T%20--%3E%20E%5B%22%F0%9F%8E%A4%20Entrevista%20Estructurada%20y%20Semiestructurada%22%5D%0A%20%20%20%20T%20--%3E%20O%5B%22%F0%9F%91%81%EF%B8%8F%20Observaci%C3%B3n%20Directa%20y%20Participante%22%5D%0A%20%20%20%20T%20--%3E%20C%5B%22%F0%9F%93%9D%20Cuestionarios%20y%20Encuestas%22%5D%0A%20%20%20%20T%20--%3E%20D%5B%22%F0%9F%93%91%20Revisi%C3%B3n%20Documental%20y%20Arqueo%20de%20Formatos%22%5D%0A%0A%20%20%20%20style%20T%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20E%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20O%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20C%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A%20%20%20%20style%20D%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<h3 id="_1-1-la-entrevista-en-profundidad" tabindex="-1">1.1 La Entrevista en Profundidad <a class="header-anchor" href="#_1-1-la-entrevista-en-profundidad" aria-label="Permalink to &quot;1.1 La Entrevista en Profundidad&quot;">​</a></h3><p>Es la técnica principal con los tomadores de decisiones y usuarios clave.</p><ul><li><strong>Entrevista Estructurada:</strong> Guion estricto de preguntas cerradas. Útil para recopilar datos demográficos o volúmenes exactos de transacciones.</li><li><strong>Entrevista Semiestructurada:</strong> Guion de temas abiertos que permite al entrevistado explicar por qué ocurren los cuellos de botella y proponer mejoras.</li><li><em>Instrumento:</em> Guion de entrevista validado con firma del entrevistado.</li></ul><h3 id="_1-2-la-observacion-directa" tabindex="-1">1.2 La Observación Directa <a class="header-anchor" href="#_1-2-la-observacion-directa" aria-label="Permalink to &quot;1.2 La Observación Directa&quot;">​</a></h3><p>Consiste en acompañar al operador durante su jornada de trabajo sin interrumpir, observando cómo manipula los libros de registro, cuánto tiempo tarda en localizar una carpeta física y qué datos anota manualmente.</p><ul><li><em>Instrumento:</em> Guía de observación de campo y lista de cotejo.</li></ul><h3 id="_1-3-revision-documental-arqueo-de-formatos" tabindex="-1">1.3 Revisión Documental (Arqueo de Formatos) <a class="header-anchor" href="#_1-3-revision-documental-arqueo-de-formatos" aria-label="Permalink to &quot;1.3 Revisión Documental (Arqueo de Formatos)&quot;">​</a></h3><p>Todo sistema que automatiza una organización debe heredar su lógica documental. El equipo debe recolectar copias de:</p><ul><li>Planillas de inscripción, fichas de registro, comprobantes de pago o entrega.</li><li>Libros de actas, formatos de inventario, minutas de asamblea.</li><li><em>Regla de oro:</em> Cada campo de texto de un formulario físico suele convertirse en una columna de una tabla de base de datos.</li></ul><hr><h2 id="🧩-capitulo-ii-requerimientos-funcionales-vs-no-funcionales-estandar-ieee-830" tabindex="-1">🧩 CAPÍTULO II: Requerimientos Funcionales vs. No Funcionales (Estándar IEEE 830) <a class="header-anchor" href="#🧩-capitulo-ii-requerimientos-funcionales-vs-no-funcionales-estandar-ieee-830" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Requerimientos Funcionales vs. No Funcionales (Estándar IEEE 830)&quot;">​</a></h2><p>Los requerimientos definen el contrato técnico entre la comunidad y el equipo desarrollador. Se dividen en dos categorías fundamentales:</p><h3 id="_2-1-requerimientos-funcionales-rf" tabindex="-1">2.1 Requerimientos Funcionales (RF) <a class="header-anchor" href="#_2-1-requerimientos-funcionales-rf" aria-label="Permalink to &quot;2.1 Requerimientos Funcionales (RF)&quot;">​</a></h3><p>Describen <strong>lo que el sistema debe hacer</strong>: los servicios que proporciona, las reacciones a entradas específicas y el comportamiento en situaciones particulares. Responden a la fórmula: <em>&quot;El sistema debe permitir a [Rol] [Acción] [Objeto/Resultado]&quot;.</em></p><table tabindex="0"><thead><tr><th>Código</th><th>Nombre del Requerimiento</th><th>Descripción Detallada</th><th>Criterio de Aceptación</th></tr></thead><tbody><tr><td><strong>RF-01</strong></td><td>Registro de Beneficiarios</td><td>El sistema debe permitir registrar los datos personales (cédula, nombres, teléfono, dirección) de los jefes de familia del sector.</td><td>La cédula debe ser única y no permitir duplicados en la base de datos.</td></tr><tr><td><strong>RF-02</strong></td><td>Control de Entrega de Insumos</td><td>El sistema debe registrar la asignación de insumos médicos por paciente, descontando automáticamente del stock.</td><td>El stock no puede quedar con valores negativos tras la transacción.</td></tr><tr><td><strong>RF-03</strong></td><td>Generación de Reportes PDF</td><td>El sistema debe generar un reporte mensual de asistencias o solicitudes en formato PDF listo para imprimir.</td><td>Debe incluir membrete institucional, fecha de emisión y totales calculados.</td></tr></tbody></table><h3 id="_2-2-requerimientos-no-funcionales-rnf" tabindex="-1">2.2 Requerimientos No Funcionales (RNF) <a class="header-anchor" href="#_2-2-requerimientos-no-funcionales-rnf" aria-label="Permalink to &quot;2.2 Requerimientos No Funcionales (RNF)&quot;">​</a></h3><p>Describen <strong>cómo debe operar el sistema</strong>: imponen restricciones sobre el diseño o la implementación (rendimiento, seguridad, usabilidad, interoperabilidad y licencias).</p><table tabindex="0"><thead><tr><th>Código</th><th>Categoría</th><th>Descripción</th><th>Métrica / Estándar</th></tr></thead><tbody><tr><td><strong>RNF-01</strong></td><td><strong>Seguridad</strong></td><td>Las contraseñas de los usuarios deben almacenarse cifradas con algoritmos seguros (bcrypt o Argon2).</td><td>Ningún texto plano de contraseña en base de datos.</td></tr><tr><td><strong>RNF-02</strong></td><td><strong>Soberanía / Software Libre</strong></td><td>El sistema debe funcionar sobre motores de bases de datos y servidores libres (PostgreSQL/MariaDB, Apache/Nginx, Linux).</td><td>Cumplimiento estricto de la Ley de Infogobierno.</td></tr><tr><td><strong>RNF-03</strong></td><td><strong>Usabilidad</strong></td><td>La interfaz de usuario debe ser intuitiva, con tamaños de letra legibles y alertas claras en español.</td><td>Tiempo de aprendizaje menor a 2 horas para usuarios con competencias básicas.</td></tr><tr><td><strong>RNF-04</strong></td><td><strong>Rendimiento</strong></td><td>Las consultas de búsqueda de registros no deben demorar más de 2 segundos en una red local con 10 usuarios concurrentes.</td><td>Tiempo de respuesta promedio &lt; 2 seg.</td></tr></tbody></table><hr><h2 id="📐-capitulo-iii-la-matriz-de-trazabilidad-de-requerimientos" tabindex="-1">📐 CAPÍTULO III: La Matriz de Trazabilidad de Requerimientos <a class="header-anchor" href="#📐-capitulo-iii-la-matriz-de-trazabilidad-de-requerimientos" aria-label="Permalink to &quot;📐 CAPÍTULO III: La Matriz de Trazabilidad de Requerimientos&quot;">​</a></h2><p>La <strong>Matriz de Trazabilidad</strong> es una herramienta fundamental de aseguramiento de calidad que vincula cada requerimiento con su origen comunitario, los módulos de software que lo satisfacen y los casos de prueba que lo validarán.</p>',21)),(o(),r(d,null,{default:a(()=>[s(i,{id:"mermaid-250",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20P%5B%22%E2%9A%A0%EF%B8%8F%20Necesidad%20Comunitaria%20(Diagn%C3%B3stico)%22%5D%20--%3E%20R%5B%22%F0%9F%93%8B%20Requerimiento%20Funcional%20(RF)%22%5D%0A%20%20%20%20R%20--%3E%20D%5B%22%F0%9F%A7%A9%20M%C3%B3dulo%20de%20Software%20%2F%20Caso%20de%20Uso%22%5D%0A%20%20%20%20D%20--%3E%20T%5B%22%E2%9C%85%20Caso%20de%20Prueba%20(QA)%22%5D%0A%0A%20%20%20%20style%20P%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A%20%20%20%20style%20R%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20D%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A%20%20%20%20style%20T%20fill%3A%2315803d%2Cstroke%3A%2322c55e%2Ccolor%3A%23fff%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<h3 id="plantilla-de-matriz-de-trazabilidad" tabindex="-1">Plantilla de Matriz de Trazabilidad <a class="header-anchor" href="#plantilla-de-matriz-de-trazabilidad" aria-label="Permalink to &quot;Plantilla de Matriz de Trazabilidad&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID Requerimiento</th><th>Necesidad Comunitaria de Origen</th><th>Prioridad (Alta/Media/Baja)</th><th>Módulo de Software Asociado</th><th>Caso de Prueba de Validación</th></tr></thead><tbody><tr><td><strong>RF-01</strong></td><td>Pérdida de fichas en papel de los habitantes del sector.</td><td><strong>Alta (Vital)</strong></td><td>Módulo de Gestión de Habitantes</td><td><code>CP-HAB-01</code>: Validar registro de cédula y persistencia en BD.</td></tr><tr><td><strong>RF-02</strong></td><td>Descontrol en la cantidad de medicinas disponibles.</td><td><strong>Alta (Vital)</strong></td><td>Módulo de Inventario y Farmacia</td><td><code>CP-INV-02</code>: Validar descuento automático y alerta de stock bajo.</td></tr><tr><td><strong>RF-03</strong></td><td>Tardanza de días en entregar informes a la alcaldía.</td><td><strong>Media</strong></td><td>Módulo de Reportes Estadísticos</td><td><code>CP-REP-01</code>: Generar exportación PDF en menos de 5 segundos.</td></tr></tbody></table><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-2" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 2 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-2" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 2&quot;">​</a></h2><p>Para la Evaluación 2, los equipos deben presentar el <strong>Documento de Especificación de Requerimientos de Software (ERS)</strong> que contendrá:</p><ol><li><strong>Instrumentos de Recolección Aplicados:</strong> Transcripción de entrevistas y muestra de formatos físicos recolectados.</li><li><strong>Catálogo de Requerimientos Funcionales (RF):</strong> Identificados y descritos bajo el estándar de ingeniería de software.</li><li><strong>Catálogo de Requerimientos No Funcionales (RNF):</strong> Restricciones de seguridad, rendimiento y cumplimiento legal de software libre.</li><li><strong>Matriz de Trazabilidad Preliminar:</strong> Conexión directa entre la necesidad comunitaria y los módulos planificados.</li></ol>',6))])}const E=l(m,[["render",f]]);export{v as __pageData,E as default};
